#!/usr/bin/env bash
# Dev-shell runtime bootstrap for ema, sourced by this repo's flake
# (./bin/dev/shell-enter.sh <PROJECT_NAME>). Must be sourced (not executed):
# the env exports must reach the interactive shell, and the MariaDB stop
# trap must bind to it. Must run from the repo root ($PWD).
#
# ema has no .env: machine paths are owned by the Makefile and re-derived
# here (relative to $PWD); the dev connection config lives in
# var/reuter.local.ini (generated by 'ema init db'), never in a shell
# export. This exports the sandbox locations + EMA_MODE, resumes the
# isolated MariaDB daemon when its data dir exists but the socket is down,
# and installs the PROJECT_NAME-scoped tmux alias. Prompt styling (PS1)
# stays in the flake shellHook so users can customize it directly.

if ! (return 0 2>/dev/null); then
    echo "shell-enter.sh must be sourced, not executed" >&2
    exit 1
fi

if [ -z "${1:-}" ]; then
    echo "usage: source shell-enter.sh <PROJECT_NAME>" >&2
    return 1 2>/dev/null || exit 1
fi
PROJECT_NAME="$1"

export EMA_REPO_PATH="$PWD"
export EMA_LIB="$EMA_REPO_PATH/src"

export MYSQL_BASE_DIR="$EMA_REPO_PATH/var/mariadb"
export MYSQL_DATA_DIR="$MYSQL_BASE_DIR/data"
export MYSQL_UNIX_PORT="$MYSQL_BASE_DIR/mysql.sock"
export MYSQL_PID_FILE="$MYSQL_BASE_DIR/mysql.pid"

export EMA_MODE="dev"

# Resume the local MariaDB daemon if the data dir exists but the server
# is not running (dev-init starts it on first run).
if [ -d "$MYSQL_DATA_DIR" ] && [ ! -S "$MYSQL_UNIX_PORT" ]; then
    echo "Starting isolated MariaDB server..."
    mysqld --datadir="$MYSQL_DATA_DIR" --pid-file="$MYSQL_PID_FILE" --socket="$MYSQL_UNIX_PORT" --skip-networking > /dev/null 2>&1 &
    MARIADB_PID=$!

    # Clean up background execution seamlessly upon exiting the shell
    trap "echo 'Stopping local MariaDB server...'; kill $MARIADB_PID; wait $MARIADB_PID 2>/dev/null" EXIT
fi

# Inherit nix shell env in tmux (doesn't include PS1)
# Requires 'set -g default-command ...' in .tmux.conf
alias tmux="command tmux -L \$PROJECT_NAME new-session -A -s \$PROJECT_NAME"
